<?php $pageTitle='Zakat Calculations';require_once __DIR__.'/../../includes/admin_header.php';$rows=tableExists($pdo,'zakat_calculations')?$pdo->query("SELECT z.*,u.full_name,u.email FROM zakat_calculations z JOIN users u ON u.id=z.user_id ORDER BY z.created_at DESC")->fetchAll():[];?><div class="bg-white rounded-2xl border overflow-hidden"><div class="p-5 border-b"><h2 class="font-bold text-lg">Zakat Calculations</h2><p class="text-sm text-slate-500">ZakatPro administration module.</p></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class='p-4 text-left'>Reference</th><th class='p-4 text-left'>User</th><th class='p-4 text-left'>Type</th><th class='p-4 text-left'>Nisab</th><th class='p-4 text-left'>Zakat</th><th class='p-4 text-left'>Payment</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t"><td class='p-4'><?=e($r['reference_no']??'—')?></td><td class='p-4'><?=e($r['full_name']??'—')?></td><td class='p-4'><?=e($r['zakat_type']??'—')?></td><td class='p-4'><?=e($r['nisab_value']??'—')?></td><td class='p-4'><?=e($r['zakat_due']??'—')?></td><td class='p-4'><?=e($r['payment_status']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div><?php require_once __DIR__.'/../../includes/admin_footer.php';?>